        switch variant {
        
        case 1: return .programMismatch(requested: try FfiConverterString.read(from: &buf), declared: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .digestMismatch(expected: try FfiConverterString.read(from: &buf), actual: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .invalid(failure: try FfiConverterTypeIdlParseFailureFfi.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

