        switch value {
        
        
        case let .programMismatch(requested,declared):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(requested, into: &buf)
            FfiConverterString.write(declared, into: &buf)
            
        
        case let .digestMismatch(expected,actual):
